vec2 uv = fragCoord / iResolution.xy;
float zoom = 1.4 + sin(iTime * 0.6) * 0.6;
vec2 p = (uv * 2.0 - 1.0) * zoom;
p.x *= iResolution.x / iResolution.y;

float ball = length(p - vec2(0.0, 0.16)) - 0.24;

float rounding = 0.08;
vec2 q = abs(p - vec2(0.0, -0.16)) - (vec2(0.3, 0.16) - rounding);
float box = length(max(q, 0.0)) - rounding;

float d = min(ball, box);
float w = fwidth(d);

float fill = 1.0 - smoothstep(-w, w, d);
float outline = 1.0 - smoothstep(w, w * 3.0, abs(d + 0.02));

vec3 colour = mix(vec3(0.05, 0.05, 0.08), vec3(0.16, 0.34, 0.5), fill);
colour = mix(colour, vec3(0.55, 0.86, 1.0), outline);

fragColor = vec4(colour, 1.0);

